import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.DEqXEGcv.js";const n="/images/issues/028/cover-bastei-bridge.jpg",s="/images/issues/028/news-copilot-slack.png",i="/images/issues/028/news-copilot-teams.png",l="/images/issues/028/news-copilot-jetbrains-settings.png",g="/images/issues/028/news-google-zero-trust-agents.png",p="/images/issues/028/news-cloudflare-bot-preference-sync.png",h="/images/issues/028/world-great-wall.jpg",c="/images/issues/028/world-abraj-clock.jpg",m="/images/issues/028/world-narendra-modi-stadium.jpg",d="/images/issues/028/world-an225.jpg",u="/images/issues/028/world-atacama.jpg",b="/images/issues/028/tool-zero-trust-agents.png",f="/images/issues/028/tool-cloudflare-agents.png",_="/images/issues/028/tool-agentteams.png",k="/images/issues/028/tool-openai-agents-python.png",y=JSON.parse('{"title":"小七的周刊（第 028 期）：当 Agent 进了群聊，护栏也要进场","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"小七的周刊（第 028 期）：当 Agent 进了群聊，护栏也要进场"}],["meta",{"property":"og:description","content":"GitHub 把 Copilot 带进 Slack 和 Teams，Google 用 ADK 演示零信任 agent，Cloudflare 开始同步 AI bot 偏好；本期关注协作型 agent 的治理、权限和可观察性。"}],["meta",{"property":"og:image","content":"https://blog.leeseven.com/images/issues/028/cover-bastei-bridge.jpg"}],["meta",{"property":"og:image:secure_url","content":"https://blog.leeseven.com/images/issues/028/cover-bastei-bridge.jpg"}],["meta",{"property":"og:image:type","content":"image/jpeg"}],["meta",{"property":"og:image:width","content":"3409"}],["meta",{"property":"og:image:height","content":"2260"}],["meta",{"property":"og:image:alt","content":"第 028 期封面图：德国萨克森瑞士国家公园的巴斯泰桥"}],["meta",{"name":"twitter:image","content":"https://blog.leeseven.com/images/issues/028/cover-bastei-bridge.jpg"}],["meta",{"itemprop":"image","content":"https://blog.leeseven.com/images/issues/028/cover-bastei-bridge.jpg"}],["meta",{"property":"og:url","content":"https://blog.leeseven.com/issues/issue-028"}]]},"headers":[],"relativePath":"issues/issue-028.md","filePath":"issues/issue-028.md","lastUpdated":1787527239000}'),A={name:"issues/issue-028.md"};function q(P,e,C,x,I,v){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="小七的周刊-第-028-期-当-agent-进了群聊-护栏也要进场" tabindex="-1">小七的周刊（第 028 期）：当 Agent 进了群聊，护栏也要进场 <a class="header-anchor" href="#小七的周刊-第-028-期-当-agent-进了群聊-护栏也要进场" aria-label="Permalink to &quot;小七的周刊（第 028 期）：当 Agent 进了群聊，护栏也要进场&quot;">​</a></h1><p><em>这里记录每周值得分享的科技内容，<strong>每周一发布</strong>（北京时间 07:00）。</em></p><hr><h2 id="本期-3-个要点" tabindex="-1">本期 3 个要点 <a class="header-anchor" href="#本期-3-个要点" aria-label="Permalink to &quot;本期 3 个要点&quot;">​</a></h2><ol><li><strong>Agent 开始进入协作现场</strong>：GitHub Copilot 同一天进入 Slack 和 Teams，说明 AI 工作不再只发生在 IDE 或命令行里。</li><li><strong>治理从配置项变成产品能力</strong>：JetBrains 托管设置、零信任 agent 示例和 bot 偏好同步，都在把权限、审计和策略前置。</li><li><strong>真正难的是“谁能让它动手”</strong>：共享会话很诱人，但只要 agent 能开 PR、改数据库或调用工具，身份、审批和可观察性就必须跟上。</li></ol><hr><h2 id="封面图" tabindex="-1">封面图 <a class="header-anchor" href="#封面图" aria-label="Permalink to &quot;封面图&quot;">​</a></h2><p><img src="'+n+'" alt="德国萨克森瑞士国家公园的巴斯泰桥"></p><p>封面图：德国萨克森瑞士国家公园的巴斯泰桥。几段石桥把分散岩峰连成可行走的路径，本期主题也类似：agent 正在跨进聊天、会议、IDE 和云沙箱，连接变多以后，真正重要的是桥面、护栏和限行标识。</p><hr><h2 id="本周短谈" tabindex="-1">本周短谈 <a class="header-anchor" href="#本周短谈" aria-label="Permalink to &quot;本周短谈&quot;">​</a></h2><h3 id="_1-agent-进群聊-不等于工作自动消失" tabindex="-1">1. Agent 进群聊，不等于工作自动消失 <a class="header-anchor" href="#_1-agent-进群聊-不等于工作自动消失" aria-label="Permalink to &quot;1. Agent 进群聊，不等于工作自动消失&quot;">​</a></h3><p>GitHub 这周连续把 Copilot 带进 Slack 和 Microsoft Teams。表面看，这是“在聊天里叫一个 agent 来帮忙”；更深一层，它把需求、讨论、上下文、执行和验收放进同一个协作现场。</p><p>这会改变很多人的第一反应。过去把任务交给 AI，常常像开一个单独窗口；现在它更像在公开讨论里拉进一位能动手的参与者。好处是上下文不容易丢，旁观者也能及时纠偏；风险是所有人都要更清楚地知道：谁有权限触发修改，哪些仓库可见，agent 产物应该在哪里被审查。</p><h3 id="_2-会不会做-之后-问题变成-能不能被约束" tabindex="-1">2. “会不会做”之后，问题变成“能不能被约束” <a class="header-anchor" href="#_2-会不会做-之后-问题变成-能不能被约束" aria-label="Permalink to &quot;2. “会不会做”之后，问题变成“能不能被约束”&quot;">​</a></h3><p>Google 的零信任 agent 示例讲得很直白：一个客服退款 agent 如果共用数据库连接、能执行代码，又只靠系统提示词守规矩，攻击者一句提示就可能把 149 美元退款改成 10,000 美元，甚至读取环境变量。</p><p>OpenAI 在 <a href="https://openai.com/index/the-defenders-window/" target="_blank" rel="noreferrer">The Defender&#39;s Window</a> 里也强调，AI 会同时放大攻击者和防守者的能力。对普通技术读者来说，这不是遥远的安全论文，而是一个产品设计问题：当 AI 变成执行者，规则要尽量落在身份、沙箱、策略网关、日志和测试里，而不是只写在一段提示词里。</p><h3 id="_3-内容和工具都在要求-可声明的边界" tabindex="-1">3. 内容和工具都在要求“可声明的边界” <a class="header-anchor" href="#_3-内容和工具都在要求-可声明的边界" aria-label="Permalink to &quot;3. 内容和工具都在要求“可声明的边界”&quot;">​</a></h3><p>Cloudflare 的 Bot Preference Sync 看起来像站长工具，但它背后是同一个趋势：AI 流量、agent 抓取、训练访问都需要可声明、可同步、可执行的偏好。网站拥有者不想在 robots.txt、一组后台开关和边缘规则之间来回维护冲突状态。</p><p>这件事和开发者很近。未来的 AI 系统不会只问“模型能不能理解我”，还会问“外部世界怎么理解这个 AI 的意图”。无论是访问网站、调用 MCP server，还是从聊天里开一个 PR，机器之间也需要更明确的交通规则。</p><hr><h2 id="科技与-ai-动态" tabindex="-1">科技与 AI 动态 <a class="header-anchor" href="#科技与-ai-动态" aria-label="Permalink to &quot;科技与 AI 动态&quot;">​</a></h2><h3 id="_1-github-copilot-进入-slack-从讨论串直接交办代码任务" tabindex="-1">1. <a href="https://github.blog/changelog/2026-08-21-the-new-github-copilot-experience-in-slack/" target="_blank" rel="noreferrer">GitHub Copilot 进入 Slack：从讨论串直接交办代码任务</a> <a class="header-anchor" href="#_1-github-copilot-进入-slack-从讨论串直接交办代码任务" aria-label="Permalink to &quot;1. [GitHub Copilot 进入 Slack：从讨论串直接交办代码任务](https://github.blog/changelog/2026-08-21-the-new-github-copilot-experience-in-slack/)&quot;">​</a></h3><p><img src="'+s+'" alt="GitHub Copilot Slack 官方发布页"></p><p>GitHub 8 月 21 日宣布，Slack 里的 GitHub 集成开始把 Copilot CLI 和 GitHub Copilot app 的 agent 能力带进 Slack，当前为公开预览。用户可以在私信、频道或讨论串里提及 <code>@GitHub</code>，让 Copilot 计划修改、调查问题、整理 bug、创建或更新 issue，并在安全云沙箱里实现和验证变更。</p><p>最值得注意的是它对“多人协作”的处理：Copilot 可以创建专门的 Slack Code channel，让参与者看计划、查 diff、审预览产物，并从原讨论继续接力。这不是简单把聊天机器人搬进 Slack，而是把 coding agent 放进工作协调层。适合先从低风险仓库试用，重点观察权限、噪音和审查流程是否跟得上。</p><h3 id="_2-copilot-进入-microsoft-teams-会议行动项可以变成共享-agent-会话" tabindex="-1">2. <a href="https://github.blog/changelog/2026-08-21-shared-agentic-work-with-github-copilot-in-microsoft-teams/" target="_blank" rel="noreferrer">Copilot 进入 Microsoft Teams：会议行动项可以变成共享 agent 会话</a> <a class="header-anchor" href="#_2-copilot-进入-microsoft-teams-会议行动项可以变成共享-agent-会话" aria-label="Permalink to &quot;2. [Copilot 进入 Microsoft Teams：会议行动项可以变成共享 agent 会话](https://github.blog/changelog/2026-08-21-shared-agentic-work-with-github-copilot-in-microsoft-teams/)&quot;">​</a></h3><p><img src="'+i+'" alt="GitHub Copilot Teams 官方发布页"></p><p>同一天，GitHub 也发布了 Copilot in Microsoft Teams 公开预览。用户可以在频道、讨论串或私信里提及 <code>@GitHub</code>，启动一个所有参与者都能看见并引导的 Copilot cloud agent session；有仓库写权限的人可以触发 Copilot 进行代码修改，相关会话会消耗 AI credits。</p><p>这让“会议结论没人落地”的老问题多了一个新解法：在讨论还没散场时，把调查、修复或验证交给云沙箱异步推进。不过边界也很清楚，agent 不应该绕过已有的代码审查。更务实的采用方式，是把 Teams 入口当成任务启动器，而不是最终决策者。</p><h3 id="_3-copilot-for-jetbrains-加入企业托管设置-插件、mcp-和遥测开始统一收口" tabindex="-1">3. <a href="https://github.blog/changelog/2026-08-18-enterprise-managed-settings-in-github-copilot-for-jetbrains/" target="_blank" rel="noreferrer">Copilot for JetBrains 加入企业托管设置：插件、MCP 和遥测开始统一收口</a> <a class="header-anchor" href="#_3-copilot-for-jetbrains-加入企业托管设置-插件、mcp-和遥测开始统一收口" aria-label="Permalink to &quot;3. [Copilot for JetBrains 加入企业托管设置：插件、MCP 和遥测开始统一收口](https://github.blog/changelog/2026-08-18-enterprise-managed-settings-in-github-copilot-for-jetbrains/)&quot;">​</a></h3><p><img src="'+l+'" alt="GitHub Copilot JetBrains 托管设置发布页"></p><p>GitHub 8 月 18 日宣布，Copilot for JetBrains 支持企业托管设置，覆盖插件治理、MCP server 访问、OpenTelemetry 和权限模式。管理员可以集中设置启用或禁用插件、额外市场、受限市场，也可以通过 <code>allowedMcpServers</code> 和 <code>deniedMcpServers</code> 管理开发者可连接的 MCP server。</p><p>这条更新不如新模型上架显眼，但对生产环境更关键。agent 进入 IDE 后，真正的风险往往不是“它答错一句话”，而是“它接了哪些工具、把遥测发到哪里、默认能执行到什么程度”。企业托管设置的价值，是让策略不再依赖每位开发者手工配置。</p><h3 id="_4-google-adk-零信任-agent-示例-不要把系统提示词当安全边界" tabindex="-1">4. <a href="https://developers.googleblog.com/build-zero-trust-ai-agents-with-googles-agent-development-kit/" target="_blank" rel="noreferrer">Google ADK 零信任 agent 示例：不要把系统提示词当安全边界</a> <a class="header-anchor" href="#_4-google-adk-零信任-agent-示例-不要把系统提示词当安全边界" aria-label="Permalink to &quot;4. [Google ADK 零信任 agent 示例：不要把系统提示词当安全边界](https://developers.googleblog.com/build-zero-trust-ai-agents-with-googles-agent-development-kit/)&quot;">​</a></h3><p><img src="'+g+'" alt="Google ADK 零信任 agent 官方文章"></p><p>Google Developers Blog 8 月 17 日介绍了用 Agent Development Kit 和 Gemini 构建的零信任 agent 示例。官方场景是一个客服与退货 agent：正常情况下，它会读取用户请求、计算退款、写入数据库账本；在攻击场景里，恶意提示可能诱导它越权退款、读取环境变量或篡改数据。</p><p>Google 的结论很直接：系统提示词不是安全边界。示例把防线拆成三层：加密身份与账本签名、受管沙箱执行、语义网关与确定性测试。对开发者来说，这套思路比“再写一条更严厉的 prompt”可靠得多，也更容易被安全审计和回归测试吸收。</p><h3 id="_5-cloudflare-bot-preference-sync-把-ai-bot-偏好同步到-robots-txt" tabindex="-1">5. <a href="https://blog.cloudflare.com/bot-preference-sync/" target="_blank" rel="noreferrer">Cloudflare Bot Preference Sync：把 AI bot 偏好同步到 robots.txt</a> <a class="header-anchor" href="#_5-cloudflare-bot-preference-sync-把-ai-bot-偏好同步到-robots-txt" aria-label="Permalink to &quot;5. [Cloudflare Bot Preference Sync：把 AI bot 偏好同步到 robots.txt](https://blog.cloudflare.com/bot-preference-sync/)&quot;">​</a></h3><p><img src="'+p+'" alt="Cloudflare Bot Preference Sync 官方文章"></p><p>Cloudflare 8 月 21 日发布 Bot Preference Sync，面向从 Free 到 Enterprise 的所有客户开放。它会把站点在 AI bot 配置里的 Search、Agent、Training 等偏好同步反映到 robots.txt，减少“后台策略禁止、公开声明没更新”或相反状态造成的冲突。</p><p>这不是只给 SEO 人员看的小功能。AI agent 越多，网站就越需要表达“哪些访问欢迎、哪些访问拒绝、哪些访问只能在特定条件下发生”。robots.txt 本身不是强制安全边界，但当偏好声明和边缘执行策略保持一致，内容拥有者与爬虫、搜索、agent 之间的摩擦会小很多。</p><hr><h2 id="世界之最" tabindex="-1">世界之最 <a class="header-anchor" href="#世界之最" aria-label="Permalink to &quot;世界之最&quot;">​</a></h2><h3 id="_1-世界最长防御工程-长城" tabindex="-1">1. 世界最长防御工程：长城 <a class="header-anchor" href="#_1-世界最长防御工程-长城" aria-label="Permalink to &quot;1. 世界最长防御工程：长城&quot;">​</a></h3><p><img src="'+h+'" alt="金山岭长城蜿蜒在山脊上"></p><p><em>长城是世界最知名的线性防御工程之一，历代墙体、壕堑和关隘共同构成庞大的边界系统。</em></p><p>长城的启发不只是“筑墙”，而是边界需要分段、关口、巡检和维护。AI 工具也是如此，最有效的防线不是一句“不要越权”，而是把访问、审批、日志和例外路径拆成可检查的节点。</p><h3 id="_2-世界最大钟面-麦加皇家钟塔" tabindex="-1">2. 世界最大钟面：麦加皇家钟塔 <a class="header-anchor" href="#_2-世界最大钟面-麦加皇家钟塔" aria-label="Permalink to &quot;2. 世界最大钟面：麦加皇家钟塔&quot;">​</a></h3><p><img src="'+c+'" alt="麦加皇家钟塔的巨大钟面"></p><p><em>麦加皇家钟塔被吉尼斯世界纪录列为最高钟楼，其钟面也常被列为世界最大钟面。</em></p><p>一个城市级钟面最重要的功能不是炫耀尺寸，而是给大量人群一个共同时间。协作型 agent 也需要类似同步信号：任务状态、执行进度、谁在审查、何时停止，都应该让参与者看得见。</p><h3 id="_3-世界最大体育场-纳伦德拉·莫迪体育场" tabindex="-1">3. 世界最大体育场：纳伦德拉·莫迪体育场 <a class="header-anchor" href="#_3-世界最大体育场-纳伦德拉·莫迪体育场" aria-label="Permalink to &quot;3. 世界最大体育场：纳伦德拉·莫迪体育场&quot;">​</a></h3><p><img src="'+m+'" alt="纳伦德拉·莫迪体育场看台"></p><p><em>纳伦德拉·莫迪体育场位于印度艾哈迈达巴德，容量约 132,000 人，通常被列为世界最大体育场。</em></p><p>十几万人同时在场，靠的不是嗓门，而是入口、分区、屏幕、安保和广播系统。把 agent 放进 Slack 或 Teams 也是这个逻辑：参与者越多，越不能只靠“大家自觉看清楚”。</p><h3 id="_4-世界最大货运飞机代表-antonov-an-225-mriya" tabindex="-1">4. 世界最大货运飞机代表：Antonov An-225 Mriya <a class="header-anchor" href="#_4-世界最大货运飞机代表-antonov-an-225-mriya" aria-label="Permalink to &quot;4. 世界最大货运飞机代表：Antonov An-225 Mriya&quot;">​</a></h3><p><img src="'+d+'" alt="Antonov An-225 Mriya 停靠在莱比锡哈雷机场"></p><p><em>Antonov An-225 Mriya 是人类制造过的最大货运飞机之一，也是超重型空运能力的代表。</em></p><p>An-225 的故事提醒人们，单体能力再惊人，也有脆弱性。技术系统同样如此：把太多关键流程压在一个超级 agent 上很诱人，但更稳的方式往往是拆分职责、保留回退，并让交接可验证。</p><h3 id="_5-世界最干旱非极地沙漠之一-阿塔卡马沙漠" tabindex="-1">5. 世界最干旱非极地沙漠之一：阿塔卡马沙漠 <a class="header-anchor" href="#_5-世界最干旱非极地沙漠之一-阿塔卡马沙漠" aria-label="Permalink to &quot;5. 世界最干旱非极地沙漠之一：阿塔卡马沙漠&quot;">​</a></h3><p><img src="'+u+'" alt="阿塔卡马沙漠荒原景观"></p><p><em>阿塔卡马沙漠位于智利北部，极端干燥和晴朗天空让它成为重要天文观测地点。</em></p><p>低噪声环境适合看见微弱信号。排查 agent 系统也一样：如果日志混乱、权限模糊、上下文到处飘，真正的错误会被噪声淹没。先把环境变干净，诊断才有可能变准确。</p><hr><h2 id="开源工具" tabindex="-1">开源工具 <a class="header-anchor" href="#开源工具" aria-label="Permalink to &quot;开源工具&quot;">​</a></h2><h3 id="_1-zero-trust-agents-用-adk-演示身份、沙箱和语义网关" tabindex="-1">1. <a href="https://github.com/GoogleCloudPlatform/generative-ai/tree/main/agents/adk/zero-trust-agents" target="_blank" rel="noreferrer">zero-trust-agents：用 ADK 演示身份、沙箱和语义网关</a> <a class="header-anchor" href="#_1-zero-trust-agents-用-adk-演示身份、沙箱和语义网关" aria-label="Permalink to &quot;1. [zero-trust-agents：用 ADK 演示身份、沙箱和语义网关](https://github.com/GoogleCloudPlatform/generative-ai/tree/main/agents/adk/zero-trust-agents)&quot;">​</a></h3><p><img src="'+b+'" alt="GoogleCloudPlatform zero-trust-agents 仓库目录"></p><p>这个示例仓库是 Google 本周文章的配套项目，目标是把零信任 agent 的三层防线做成可运行蓝图：交易签名与审计账本、受控代码执行环境、语义网关和测试用例。它不适合直接当生产框架复制粘贴，但很适合用来和产品、安全、后端一起讨论“agent 到底能碰什么”。</p><p>如果你正在做会写数据库、调支付或跑代码的 agent，这个仓库值得先看。它的价值不在炫技，而在把风险拆得足够具体：越权退款、密钥泄露、数据库篡改都能映射到对应控制点。</p><h3 id="_2-cloudflare-agents-把-agent-做成有状态、可休眠的执行环境" tabindex="-1">2. <a href="https://github.com/cloudflare/agents" target="_blank" rel="noreferrer">Cloudflare Agents：把 agent 做成有状态、可休眠的执行环境</a> <a class="header-anchor" href="#_2-cloudflare-agents-把-agent-做成有状态、可休眠的执行环境" aria-label="Permalink to &quot;2. [Cloudflare Agents：把 agent 做成有状态、可休眠的执行环境](https://github.com/cloudflare/agents)&quot;">​</a></h3><p><img src="'+f+'" alt="Cloudflare Agents 仓库页面"></p><p>Cloudflare Agents 是一个基于 Durable Objects 的 agent 运行环境，支持持久状态、存储、生命周期、实时通信、调度、模型调用、MCP 和 workflows。官方强调 agent 闲置时可以休眠、按需唤醒，适合“一人一个会话、一个房间一个 agent”这类高并发场景。</p><p>它对开发者的启发是：agent 不是只能存在于一次 API 调用里，也可以是长期存在的状态对象。采用时要注意平台绑定和调试方式，但如果应用本来就在 Cloudflare 生态里，它提供了一条很清楚的部署路径。</p><h3 id="_3-agentteams-把多-agent-协作放进可见房间" tabindex="-1">3. <a href="https://github.com/agentscope-ai/AgentTeams" target="_blank" rel="noreferrer">AgentTeams：把多 agent 协作放进可见房间</a> <a class="header-anchor" href="#_3-agentteams-把多-agent-协作放进可见房间" aria-label="Permalink to &quot;3. [AgentTeams：把多 agent 协作放进可见房间](https://github.com/agentscope-ai/AgentTeams)&quot;">​</a></h3><p><img src="'+_+'" alt="AgentTeams GitHub 仓库页面"></p><p>AgentTeams 是一个开源多 agent 协作运行平台，核心思路是让多个 agent 在受控、可审计的房间里协作，并保留人工可见性和介入能力。它使用 Manager-Workers 架构，强调 OpenClaw、QwenPaw、Hermes 等不同运行时可以在同一协作空间里分工。</p><p>这类工具适合观察“多 agent”从演示走向工程时会遇到什么：共享文件、角色分配、任务接力、房间记录、网关和审计。它不是最轻量的起步方式，但能提醒读者，多 agent 的难点常常不是让它们说话，而是让它们有秩序地交接。</p><h3 id="_4-openai-agents-sdk-把-handoff、guardrails、hitl-和-tracing-放进同一个框架" tabindex="-1">4. <a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noreferrer">OpenAI Agents SDK：把 handoff、guardrails、HITL 和 tracing 放进同一个框架</a> <a class="header-anchor" href="#_4-openai-agents-sdk-把-handoff、guardrails、hitl-和-tracing-放进同一个框架" aria-label="Permalink to &quot;4. [OpenAI Agents SDK：把 handoff、guardrails、HITL 和 tracing 放进同一个框架](https://github.com/openai/openai-agents-python)&quot;">​</a></h3><p><img src="'+k+'" alt="OpenAI Agents SDK Python 仓库页面"></p><p>OpenAI Agents SDK 是一个用于构建多 agent workflow 的 Python 框架，仓库说明里列出了 agents、tools、handoffs、guardrails、human in the loop、sessions 和 tracing 等模块。它的重点不是单次问答，而是把长流程里的委派、保护和记录纳入同一套开发模型。</p><p>如果只是做一个聊天功能，它可能显得偏重；但当任务开始跨工具、跨步骤、跨审批时，框架提供的结构会比手写一堆回调更容易维护。读者可以重点看 human in the loop 和 tracing，两者决定了 agent 出错时是否能停下来、查回去。</p><hr><h2 id="本周冷知识-彩蛋" tabindex="-1">本周冷知识 / 彩蛋 <a class="header-anchor" href="#本周冷知识-彩蛋" aria-label="Permalink to &quot;本周冷知识 / 彩蛋&quot;">​</a></h2><ul><li><strong>冷知识 1</strong>：robots.txt 更像“访问偏好声明”，不是强制门禁。真正阻断仍要靠服务端、边缘规则或身份策略，但声明和执行不一致会让 AI bot 治理变得很混乱。</li><li><strong>冷知识 2</strong>：巴斯泰桥所在的砂岩地貌由长期水蚀形成，后来才被人类加上桥面。很多技术系统也是这样：自然形成的沟壑先存在，工程做的是让跨越变得可控。</li></ul><hr><h2 id="小七的碎碎念" tabindex="-1">小七的碎碎念 <a class="header-anchor" href="#小七的碎碎念" aria-label="Permalink to &quot;小七的碎碎念&quot;">​</a></h2><p>这周的关键词不是“更聪明”，而是“更像同事”：agent 会出现在群聊、会议、工单和 IDE 里，甚至会带着一段上下文去开 PR。</p><p>可一旦它像同事一样能动手，就也要像同事一样被授权、被记录、被审查。把护栏做早一点，往往比事后补一篇事故说明便宜得多。</p><hr><h2 id="互动钩子" tabindex="-1">互动钩子 <a class="header-anchor" href="#互动钩子" aria-label="Permalink to &quot;互动钩子&quot;">​</a></h2><p>如果一个 agent 可以从聊天里直接创建 PR，你最希望先看到哪三件事：权限范围、执行日志、回滚方案，还是人工确认点？</p><hr><h2 id="本周行动清单" tabindex="-1">本周行动清单 <a class="header-anchor" href="#本周行动清单" aria-label="Permalink to &quot;本周行动清单&quot;">​</a></h2><ul><li>盘点一个项目里所有 AI 工具入口：聊天、IDE、CLI、MCP server、浏览器插件，标出它们能读写什么。</li><li>把一个高风险工具调用改成需要显式确认，例如支付、删库、发邮件、开 PR 或部署。</li><li>给 agent 任务补最小可用日志：谁触发、用了哪些上下文、调用了哪些工具、产物在哪里审查。</li><li>选择一个低风险流程试验共享 agent 会话，并提前写清停止条件和验收标准。</li></ul><hr><p>我们下周见。</p>',97)])])}const S=a(A,[["render",q]]);export{y as __pageData,S as default};
